stylesheet:
QMainWindow { background-color: #f6f1e6; }
QTreeWidget { background-color: #f9f4ea; alternate-background-color: #efe5d2; color: #3a2f1f; border: 1px solid #d7c7ac; }
QTreeWidget::item:selected { background-color: #c9a86a; color: #2b2012; }
QGroupBox { border: 1px solid #d7c7ac; border-radius: 6px; margin-top: 10px; padding: 10px; }
QGroupBox::title { subcontrol-origin: margin; left: 10px; padding: 0 3px 0 3px; }
QTextEdit { background-color: #f9f4ea; color: #3a2f1f; border: 1px solid #d7c7ac; }
QPushButton { background-color: #e4d6bf; color: #3a2f1f; border-radius: 4px; padding: 4px 10px; }
QPushButton:hover { background-color: #d9c7ab; }
QPushButton:pressed { background-color: #cbb48d; }
QLabel { color: #3a2f1f; }
QMenu { background-color: #f9f4ea; color: #3a2f1f; border: 1px solid #d7c7ac; }
QMenu::item { padding: 4px 20px 4px 24px; background-color: transparent; }
QMenu::item:selected { background-color: #c9a86a; color: #2b2012; }
QMenu::separator { height: 1px; background: #d7c7ac; margin-left: 4px; margin-right: 4px; }
